questionvariables.text:
/* Distance from object */
d: rand(10) + 10;

/* Angle */
theta: rand([30, 35, 40, 45, 50, 55, 60]);

/* Height calculation evaluated natively as a float */
h: float(d * tan(theta * %pi / 180));

/* Display variable formatted to exactly 2 decimal places */
h_disp: dispdp(h, 2);

/* Mistakes */
m1: float(d / tan(theta * %pi / 180)); /* Inverted tangent */
m2: float(d * sin(theta * %pi / 180)); /* Used sine */
m3: float(d * cos(theta * %pi / 180)); /* Used cosine */
